[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — UI & UX Design Inspiration Library</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #ffffff;
      --surface: #f5f5f5;
      --surface-2: #ebebeb;
      --border: #e5e5e5;
      --border-dark: #d4d4d4;
      --text: #141414;
      --text-muted: #737373;
      --text-light: #a3a3a3;
      --accent: #5b5cf6;
      --accent-hover: #4a4ae0;
      --accent-light: #eeeeff;
      --radius-sm: 8px;
      --radius: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
      --shadow: 0 4px 16px rgba(0,0,0,.08), 0 2px 6px rgba(0,0,0,.04);
      --shadow-lg: 0 12px 40px rgba(0,0,0,.12), 0 4px 12px rgba(0,0,0,.06);
      --font: 'Inter', system-ui, -apple-system, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ─── Announcement Bar ─── */
    .announcement-bar {
      background: var(--text);
      color: #fff;
      text-align: center;
      padding: 10px 1rem;
      font-size: 0.8125rem;
      font-weight: 500;
      letter-spacing: 0.01em;
    }
    .announcement-bar a { color: #a5b4fc; text-decoration: none; margin-left: 6px; }
    .announcement-bar a:hover { text-decoration: underline; }

    /* ─── Navigation ─── */
    nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
      padding: 0 1.5rem;
    }
    .nav-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 60px;
    }
    .nav-logo {
      font-size: 1.0625rem;
      font-weight: 800;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.03em;
    }
    .nav-logo span { color: var(--accent); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      list-style: none;
    }
    .nav-links a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-muted);
      text-decoration: none;
      padding: 6px 12px;
      border-radius: var(--radius-sm);
      transition: color 150ms, background 150ms;
    }
    .nav-links a:hover { color: var(--text); background: var(--surface); }
    .nav-cta {
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      font-family: var(--font);
      font-size: 0.875rem;
      font-weight: 600;
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      text-decoration: none;
      transition: all 150ms ease;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--accent);
      color: #fff;
      padding: 9px 18px;
      box-shadow: 0 0 0 0 rgba(91,92,246,0.4);
    }
    .btn-primary:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
      box-shadow: 0 4px 16px rgba(91,92,246,0.35);
    }
    .btn-primary:active { transform: translateY(0); }
    .btn-ghost {
      background: transparent;
      color: var(--text-muted);
      padding: 9px 18px;
      border: 1px solid var(--border);
    }
    .btn-ghost:hover { color: var(--text); border-color: var(--border-dark); background: var(--surface); }
    .btn-lg {
      font-size: 0.9375rem;
      padding: 13px 28px;
      border-radius: 10px;
    }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }

    /* ─── Hero ─── */
    .hero {
      padding: 5rem 1.5rem 3rem;
      text-align: center;
      background: linear-gradient(180deg, #fafafe 0%, #ffffff 100%);
    }
    .hero-inner { max-width: 760px; margin: 0 auto; }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--accent-light);
      color: var(--accent);
      border: 1px solid rgba(91,92,246,0.18);
      border-radius: 100px;
      padding: 5px 14px;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      margin-bottom: 1.5rem;
    }
    .hero h1 {
      font-size: clamp(2.25rem, 6vw, 3.75rem);
      font-weight: 900;
      line-height: 1.1;
      letter-spacing: -0.04em;
      color: var(--text);
      margin-bottom: 1.25rem;
    }
    .hero-subtitle {
      font-size: 1.0625rem;
      color: var(--text-muted);
      max-width: 520px;
      margin: 0 auto 2rem;
      line-height: 1.65;
    }
    .hero-actions {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.75rem;
      flex-wrap: wrap;
      margin-bottom: 3.5rem;
    }
    .hero-note {
      font-size: 0.75rem;
      color: var(--text-light);
      margin-top: 0.75rem;
    }

    /* Hero visual */
    .hero-visual {
      position: relative;
      max-width: 960px;
      margin: 0 auto;
    }
    .hero-browser {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg), 0 0 0 1px rgba(0,0,0,.04);
      overflow: hidden;
    }
    .browser-chrome {
      background: #fafafa;
      border-bottom: 1px solid var(--border);
      padding: 10px 16px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .browser-dots { display: flex; gap: 6px; }
    .browser-dot {
      width: 12px; height: 12px;
      border-radius: 50%;
    }
    .browser-dot:nth-child(1) { background: #ff5f57; }
    .browser-dot:nth-child(2) { background: #febc2e; }
    .browser-dot:nth-child(3) { background: #28c840; }
    .browser-url {
      flex: 1;
      background: var(--surface-2);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 5px 12px;
      font-size: 0.75rem;
      color: var(--text-muted);
      text-align: center;
    }
    .browser-content {
      padding: 1.25rem;
    }
    .screenshot-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 10px;
    }
    .screenshot-card {
      border-radius: var(--radius-sm);
      overflow: hidden;
      aspect-ratio: 9/16;
      position: relative;
      background: linear-gradient(135deg, var(--surface-2) 0%, var(--border) 100%);
      box-shadow: var(--shadow-sm);
      transition: transform 200ms ease, box-shadow 200ms ease;
    }
    .screenshot-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); }
    .screenshot-card img { width: 100%; height: 100%; object-fit: cover; }
    .screenshot-shimmer {
      display: flex;
      flex-direction: column;
      padding: 12px 10px;
      gap: 8px;
      height: 100%;
    }
    .shimmer-bar {
      height: 8px;
      border-radius: 4px;
      background: linear-gradient(90deg, var(--border) 0%, var(--border-dark) 50%, var(--border) 100%);
      background-size: 200% 100%;
      animation: shimmer 1.8s ease-in-out infinite;
    }
    @keyframes shimmer { 0%,100% { background-position: 200% 0; } 50% { background-position: -200% 0; } }
    .shimmer-bar.short { width: 60%; }
    .shimmer-bar.medium { width: 80%; }
    .shimmer-rect {
      flex: 1;
      border-radius: 6px;
      background: linear-gradient(90deg, var(--border) 0%, var(--border-dark) 50%, var(--border) 100%);
      background-size: 200% 100%;
      animation: shimmer 1.8s ease-in-out infinite;
      animation-delay: var(--d, 0s);
    }

    /* ─── Trusted By ─── */
    .trusted-by {
      padding: 3.5rem 1.5rem;
      background: var(--bg);
      border-top: 1px solid var(--border);
    }
    .trusted-label {
      text-align: center;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-light);
      margin-bottom: 2rem;
    }
    .marquee-track {
      display: flex;
      gap: 3rem;
      overflow: hidden;
      position: relative;
    }
    .marquee-track::before,
    .marquee-track::after {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      width: 80px;
      z-index: 2;
      pointer-events: none;
    }
    .marquee-track::before { left: 0; background: linear-gradient(90deg, #fff, transparent); }
    .marquee-track::after { right: 0; background: linear-gradient(270deg, #fff, transparent); }
    .marquee-inner {
      display: flex;
      gap: 3rem;
      animation: marquee-left 30s linear infinite;
      white-space: nowrap;
      flex-shrink: 0;
    }
    .marquee-inner.clone { animation: marquee-left 30s linear infinite; }
    @keyframes marquee-left {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    .brand-logo {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.9375rem;
      font-weight: 700;
      color: var(--text-light);
      letter-spacing: -0.02em;
      white-space: nowrap;
      transition: color 200ms;
    }
    .brand-logo:hover { color: var(--text-muted); }
    .brand-icon {
      width: 28px;
      height: 28px;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
    }

    /* ─── Stats ─── */
    .stats {
      padding: 5rem 1.5rem;
      background: var(--text);
      color: #fff;
    }
    .stats-inner {
      max-width: 900px;
      margin: 0 auto;
      text-align: center;
    }
    .stats-label {
      font-size: 0.8125rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: #6b7280;
      margin-bottom: 1rem;
    }
    .stats-headline {
      font-size: clamp(1.5rem, 3.5vw, 2.25rem);
      font-weight: 700;
      letter-spacing: -0.03em;
      color: #fff;
      margin-bottom: 3.5rem;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2px;
    }
    .stat-item {
      padding: 2.5rem 1.5rem;
      background: #1c1c1c;
      position: relative;
    }
    .stat-item:first-child { border-radius: var(--radius) 0 0 var(--radius); }
    .stat-item:last-child { border-radius: 0 var(--radius) var(--radius) 0; }
    .stat-number {
      font-size: clamp(2.5rem, 6vw, 4rem);
      font-weight: 900;
      letter-spacing: -0.04em;
      color: #fff;
      line-height: 1;
      margin-bottom: 0.5rem;
      font-variant-numeric: tabular-nums;
    }
    .stat-number .accent { color: var(--accent); }
    .stat-desc {
      font-size: 0.875rem;
      color: #6b7280;
      font-weight: 500;
    }

    /* ─── Section shared ─── */
    .section { padding: 5rem 1.5rem; }
    .section-inner { max-width: 1100px; margin: 0 auto; }
    .section-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 0.75rem;
    }
    .section-headline {
      font-size: clamp(1.75rem, 4vw, 2.75rem);
      font-weight: 800;
      letter-spacing: -0.035em;
      line-height: 1.15;
      color: var(--text);
      margin-bottom: 1rem;
    }
    .section-sub {
      font-size: 1rem;
      color: var(--text-muted);
      max-width: 520px;
      line-height: 1.65;
    }

    /* ─── Features: Search ─── */
    .features-search { background: var(--surface); }
    .features-search .section-inner { display: grid; grid-template-columns: 1fr; gap: 3rem; }
    .search-header { text-align: center; }
    .search-header .section-sub { margin: 0 auto; }

    /* Tabs */
    .tab-bar {
      display: flex;
      gap: 4px;
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 4px;
      width: fit-content;
      margin: 0 auto 1.5rem;
      flex-wrap: wrap;
    }
    .tab-btn {
      font-family: var(--font);
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--text-muted);
      background: transparent;
      border: none;
      padding: 7px 16px;
      border-radius: 6px;
      cursor: pointer;
      transition: all 200ms ease;
      white-space: nowrap;
    }
    .tab-btn:hover { color: var(--text); background: var(--surface); }
    .tab-btn.active { background: var(--accent); color: #fff; }

    /* Filter pills */
    .filter-row {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 4px;
      scrollbar-width: none;
      justify-content: center;
      flex-wrap: wrap;
      margin-bottom: 1.75rem;
    }
    .filter-row::-webkit-scrollbar { display: none; }
    .pill {
      font-family: var(--font);
      font-size: 0.8125rem;
      font-weight: 500;
      padding: 6px 16px;
      border-radius: 100px;
      border: 1.5px solid var(--border);
      background: var(--bg);
      color: var(--text-muted);
      cursor: pointer;
      white-space: nowrap;
      transition: all 200ms ease;
    }
    .pill:hover { border-color: var(--text-muted); color: var(--text); }
    .pill.active { background: var(--text); color: #fff; border-color: var(--text); }

    /* Screenshot grid in search */
    .search-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
      gap: 12px;
    }
    .search-card {
      border-radius: var(--radius-sm);
      overflow: hidden;
      aspect-ratio: 9/16;
      background: linear-gradient(135deg, var(--surface-2) 0%, var(--border) 100%);
      box-shadow: var(--shadow-sm);
      transition: transform 220ms ease, box-shadow 220ms ease, opacity 250ms ease;
      position: relative;
    }
    .search-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
    .search-card.fade-out { opacity: 0; transform: scale(0.97); }
    .search-card.fade-in { opacity: 1; transform: scale(1); }
    .card-label {
      position: absolute;
      bottom: 8px;
      left: 8px;
      right: 8px;
      background: rgba(0,0,0,0.7);
      color: #fff;
      font-size: 0.6875rem;
      font-weight: 600;
      padding: 4px 8px;
      border-radius: 5px;
      backdrop-filter: blur(8px);
    }
    .tab-content { display: none; }
    .tab-content.active { display: block; }

    /* Elements & Flows tab content */
    .elements-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 12px;
    }
    .element-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: var(--shadow-sm);
      transition: box-shadow 200ms, transform 200ms;
    }
    .element-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .element-preview {
      background: var(--surface);
      border-radius: var(--radius-sm);
      height: 80px;
      margin-bottom: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }
    .element-chip {
      background: var(--accent);
      color: #fff;
      border-radius: 6px;
      padding: 6px 12px;
      font-size: 0.75rem;
      font-weight: 600;
    }
    .element-chip.ghost { background: transparent; border: 1.5px solid var(--border-dark); color: var(--text-muted); }
    .element-name { font-size: 0.8125rem; font-weight: 600; color: var(--text); }
    .element-count { font-size: 0.75rem; color: var(--text-light); margin-top: 2px; }

    .flows-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
      gap: 12px;
    }
    .flow-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: box-shadow 200ms, transform 200ms;
    }
    .flow-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
    .flow-screens {
      display: flex;
      gap: 6px;
      padding: 12px;
      background: var(--surface);
    }
    .flow-screen-mini {
      flex: 1;
      aspect-ratio: 9/16;
      border-radius: 4px;
      background: var(--border);
    }
    .flow-info { padding: 10px 12px; }
    .flow-name { font-size: 0.8125rem; font-weight: 600; color: var(--text); }
    .flow-steps { font-size: 0.75rem; color: var(--text-light); margin-top: 2px; }

    .text-search-box {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1.5rem;
    }
    .text-search-input {
      width: 100%;
      border: 1.5px solid var(--border-dark);
      border-radius: var(--radius-sm);
      padding: 10px 14px;
      font-family: var(--font);
      font-size: 0.875rem;
      color: var(--text);
      background: var(--bg);
      margin-bottom: 1rem;
      outline: none;
      transition: border-color 200ms;
    }
    .text-search-input:focus { border-color: var(--accent); }
    .text-results { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px; }
    .text-result-card {
      background: var(--surface);
      border-radius: var(--radius-sm);
      aspect-ratio: 9/16;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      gap: 6px;
    }
    .text-highlight {
      background: #fef08a;
      color: #713f12;
      padding: 2px 6px;
      border-radius: 4px;
      font-size: 0.6875rem;
      font-weight: 700;
    }

    /* ─── Features: Flows ─── */
    .features-flows { background: var(--bg); }
    .flows-layout {
      display: grid;
      grid-template-columns: 1fr 1.6fr;
      gap: 4rem;
      align-items: center;
    }
    .toggle-group {
      display: flex;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 4px;
      width: fit-content;
      gap: 4px;
      margin-bottom: 1.5rem;
    }
    .toggle-btn {
      font-family: var(--font);
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--text-muted);
      background: transparent;
      border: none;
      padding: 8px 18px;
      border-radius: 6px;
      cursor: pointer;
      transition: all 200ms ease;
    }
    .toggle-btn.active { background: var(--bg); color: var(--text); box-shadow: var(--shadow-sm); }
    .flows-feature-list { list-style: none; margin-top: 1rem; }
    .flows-feature-list li {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding: 1rem 0;
      border-bottom: 1px solid var(--border);
    }
    .flows-feature-list li:last-child { border-bottom: none; }
    .feature-icon {
      width: 36px; height: 36px;
      border-radius: 8px;
      background: var(--accent-light);
      color: var(--accent);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 16px;
    }
    .feature-text h4 { font-size: 0.9375rem; font-weight: 700; margin-bottom: 2px; }
    .feature-text p { font-size: 0.8125rem; color: var(--text-muted); line-height: 1.55; }

    .flows-visual {
      position: relative;
    }
    .flows-visual-content {
      background: var(--text);
      border-radius: var(--radius-xl);
      padding: 1.5rem;
      box-shadow: var(--shadow-lg);
      min-height: 360px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .flows-video-mockup {
      width: 100%;
      display: none;
    }
    .flows-video-mockup.active { display: block; }
    .flows-proto-mockup {
      width: 100%;
      display: none;
    }
    .flows-proto-mockup.active { display: block; }
    .phone-frame {
      width: 200px;
      margin: 0 auto;
      background: #fff;
      border-radius: 28px;
      overflow: hidden;
      box-shadow: 0 24px 64px rgba(0,0,0,0.5);
      border: 2px solid #333;
    }
    .phone-screen {
      width: 100%;
      aspect-ratio: 9/19.5;
      background: linear-gradient(160deg, #f0f4ff 0%, #e8e4ff 100%);
      display: flex;
      flex-direction: column;
      padding: 1rem;
      gap: 8px;
    }
    .phone-bar { height: 8px; background: rgba(91,92,246,.3); border-radius: 4px; }
    .phone-bar.accent { background: var(--accent); width: 60%; }
    .phone-rect { flex: 1; background: rgba(91,92,246,.12); border-radius: 8px; }
    .proto-steps {
      display: flex;
      gap: 8px;
      margin-top: 1rem;
      justify-content: center;
    }
    .proto-step {
      width: 36px; height: 36px;
      border-radius: 50%;
      border: 1.5px solid #444;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #666;
      font-size: 11px;
      font-weight: 700;
      cursor: pointer;
      transition: all 200ms;
    }
    .proto-step.active { background: var(--accent); border-color: var(--accent); color: #fff; }
    .play-badge {
      width: 56px; height: 56px;
      background: rgba(255,255,255,0.15);
      border: 1.5px solid rgba(255,255,255,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 1rem;
      font-size: 20px;
      cursor: pointer;
      transition: background 200ms;
    }
    .play-badge:hover { background: rgba(255,255,255,0.25); }

    /* ─── Features: Tools ─── */
    .features-tools { background: var(--surface); }
    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
      margin-top: 3rem;
    }
    .tool-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform 220ms ease, box-shadow 220ms ease;
    }
    .tool-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
    .tool-preview {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .tool-preview-figma { background: linear-gradient(135deg, #e8fff9 0%, #d1f5e8 100%); }
    .tool-preview-save { background: linear-gradient(135deg, #eef0ff 0%, #dde0ff 100%); }
    .tool-preview-comment { background: linear-gradient(135deg, #fff8ee 0%, #ffecd1 100%); }
    .tool-preview-icon { font-size: 3rem; }
    .figma-logo {
      width: 48px; height: 48px;
      background: #1e1e1e;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
    }
    .tool-body { padding: 1.25rem; }
    .tool-tag {
      font-size: 0.6875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 0.5rem;
    }
    .tool-body h3 { font-size: 1rem; font-weight: 700; margin-bottom: 0.375rem; letter-spacing: -0.02em; }
    .tool-body p { font-size: 0.8125rem; color: var(--text-muted); line-height: 1.55; }

    /* ─── Testimonials ─── */
    .testimonials { padding: 5rem 0; overflow: hidden; background: var(--bg); }
    .testimonials-header { text-align: center; margin-bottom: 3rem; padding: 0 1.5rem; }
    .testimonials-rows { display: flex; flex-direction: column; gap: 16px; }
    .testimonial-marquee {
      display: flex;
      gap: 16px;
      overflow: hidden;
    }
    .testimonial-track {
      display: flex;
      gap: 16px;
      animation: marquee-l 40s linear infinite;
      flex-shrink: 0;
    }
    .testimonial-track.rev {
      animation: marquee-r 40s linear infinite;
    }
    @keyframes marquee-l {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    @keyframes marquee-r {
      0% { transform: translateX(-50%); }
      100% { transform: translateX(0); }
    }
    .testimonial-card {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 1.5rem;
      width: 340px;
      flex-shrink: 0;
      box-shadow: var(--shadow-sm);
    }
    .testimonial-card:hover { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(91,92,246,.08); }
    .testimonial-quote {
      font-size: 0.875rem;
      color: var(--text);
      line-height: 1.65;
      margin-bottom: 1.25rem;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .author-avatar {
      width: 36px; height: 36px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.8125rem;
      font-weight: 700;
      color: #fff;
      flex-shrink: 0;
    }
    .author-name { font-size: 0.875rem; font-weight: 700; color: var(--text); line-height: 1.2; }
    .author-company { font-size: 0.75rem; color: var(--text-light); }
    .stars {
      display: flex;
      gap: 2px;
      margin-bottom: 0.875rem;
      color: #f59e0b;
      font-size: 0.875rem;
    }

    /* ─── CTA Section ─── */
    .cta-section {
      background: var(--text);
      padding: 5rem 1.5rem 0;
      overflow: hidden;
    }
    .cta-inner {
      max-width: 640px;
      margin: 0 auto;
      text-align: center;
      padding-bottom: 3.5rem;
    }
    .cta-inner h2 {
      font-size: clamp(1.875rem, 5vw, 3rem);
      font-weight: 900;
      letter-spacing: -0.04em;
      line-height: 1.1;
      color: #fff;
      margin-bottom: 1rem;
    }
    .cta-inner p { font-size: 1rem; color: #9ca3af; margin-bottom: 2rem; line-height: 1.65; }
    .cta-actions { display: flex; gap: 0.75rem; justify-content: center; flex-wrap: wrap; }
    .btn-primary-dark {
      background: #fff;
      color: var(--text);
    }
    .btn-primary-dark:hover { background: #f5f5f5; transform: translateY(-1px); }
    .btn-ghost-dark {
      background: transparent;
      color: #9ca3af;
      border: 1px solid #374151;
    }
    .btn-ghost-dark:hover { color: #fff; border-color: #6b7280; background: #1f2937; }
    .app-marquees {
      margin-top: 3.5rem;
      display: flex;
      flex-direction: column;
      gap: 12px;
      overflow: hidden;
    }
    .app-marquee-row {
      display: flex;
      gap: 12px;
    }
    .app-icon-track {
      display: flex;
      gap: 12px;
      animation: marquee-l 24s linear infinite;
      flex-shrink: 0;
    }
    .app-icon-track.rev { animation: marquee-r 24s linear infinite; }
    .app-icon {
      width: 56px; height: 56px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.25rem;
      flex-shrink: 0;
      border: 1px solid #2d2d2d;
    }

    /* ─── Footer ─── */
    footer {
      background: var(--text);
      border-top: 1px solid #262626;
      padding: 3.5rem 1.5rem 2rem;
      color: #9ca3af;
    }
    .footer-inner {
      max-width: 1100px;
      margin: 0 auto;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr;
      gap: 3rem;
      padding-bottom: 2.5rem;
      border-bottom: 1px solid #262626;
      margin-bottom: 2rem;
    }
    .footer-brand-logo {
      font-size: 1.125rem;
      font-weight: 800;
      color: #fff;
      letter-spacing: -0.03em;
      margin-bottom: 0.75rem;
    }
    .footer-brand-logo span { color: var(--accent); }
    .footer-tagline { font-size: 0.875rem; color: #6b7280; line-height: 1.6; max-width: 260px; }
    .footer-col h4 { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #6b7280; margin-bottom: 1rem; }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
    .footer-col a { font-size: 0.875rem; color: #9ca3af; text-decoration: none; transition: color 150ms; }
    .footer-col a:hover { color: #fff; }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 0.8125rem;
      color: #6b7280;
      flex-wrap: wrap;
      gap: 0.5rem;
    }
    .footer-bottom a { color: #6b7280; text-decoration: none; }
    .footer-bottom a:hover { color: #9ca3af; }

    /* ─── Responsive ─── */
    @media (max-width: 1024px) {
      .tools-grid { grid-template-columns: repeat(2, 1fr); }
      .flows-layout { grid-template-columns: 1fr; }
      .flows-visual { display: none; }
      .stats-grid { gap: 1px; }
    }
    @media (max-width: 768px) {
      .screenshot-grid { grid-template-columns: repeat(3, 1fr); }
      .tools-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: 1fr; gap: 2px; }
      .stat-item:first-child { border-radius: var(--radius) var(--radius) 0 0; }
      .stat-item:last-child { border-radius: 0 0 var(--radius) var(--radius); }
      .stat-item:nth-child(2) { border-radius: 0; }
      .footer-top { grid-template-columns: 1fr; gap: 2rem; }
      nav .nav-links { display: none; }
      .nav-mobile-toggle { display: block; }
      .hero { padding: 3rem 1rem 2rem; }
      .browser-content { display: none; }
      .hero-visual { display: none; }
    }
    @media (max-width: 480px) {
      .screenshot-grid { grid-template-columns: repeat(2, 1fr); }
      .tab-bar { width: 100%; justify-content: center; }
      .tab-btn { font-size: 0.75rem; padding: 6px 10px; }
    }

    /* Utility */
    .text-center { text-align: center; }
    .mt-2 { margin-top: 0.5rem; }
    .mt-4 { margin-top: 1rem; }
    .mb-0 { margin-bottom: 0 !important; }
  </style>
</head>
